```sql
START TRANSACTION;

-- 1. Crear alumno
INSERT INTO alumnos (nombre, apellido, email, fecha_nacimiento)
VALUES ('Nuevo', 'Alumno', 'nuevo@email.com', '2006-01-15');

SET @id_nuevo = LAST_INSERT_ID();

-- 2. Matricular en Bases de datos
SET @id_bd = (SELECT id FROM asignaturas WHERE nombre = 'Bases de datos');

INSERT INTO matriculas (id_alumno, id_asignatura)
VALUES (@id_nuevo, @id_bd);

-- 3. Nota inicial
INSERT INTO notas (id_alumno, id_asignatura, nota, convocatoria)
VALUES (@id_nuevo, @id_bd, 0, 'Pendiente');

-- 4. Confirmar
COMMIT;

-- Si algo falla en cualquier paso, ejecutar:
-- ROLLBACK;

-- Verificar
SELECT a.nombre, asig.nombre AS asignatura, n.nota
FROM alumnos a
INNER JOIN notas n ON a.id = n.id_alumno
INNER JOIN asignaturas asig ON n.id_asignatura = asig.id
WHERE a.id = @id_nuevo;
```

Si el INSERT de matrículas falla (por ejemplo, si el alumno ya está matriculado), el ROLLBACK deshace el INSERT del alumno y la BD queda como estaba.
